{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "MISSING",
      "chunk_id": "text_8",
      "quote": "Integrative reviews can include diverse data sources and do not restrict the type of study design. Furthermore, integrative reviews take a more flexible approach to analysis compared to systematic reviews, combining both quantitative and qualitative data if there are similarities [12-14].",
      "reason": "The manuscript identifies the work as an 'integrative review' (not a 'systematic review') in the methods/design description and abstract; the title does not label the report as a 'systematic review'. Therefore it does not meet the requirement to identify the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Through an integrative review, we aimed to identify approaches to evaluate the sustainability of evidence-based interventions (EBIs) and sustainability outcomes.",
      "reason": "The title (as reflected by the study aim in the abstract) clearly indicates the main objective/review question — identifying approaches to evaluate the sustainability of evidence-based interventions in healthcare — providing the population/context (healthcare) and intervention focus (evidence-based interventions)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We conducted an integrative review that followed Whittemore and Knafl's [12] five-stage methodological process: (1) problem identification; (2) literature search; (3) data evaluation; (4) data analysis (data reduction, display, comparison, and conclusions); and (5) presentation.",
      "reason": "The title (and manuscript) specify the review type as an 'integrative review' and the methods description states the methodological process used; additionally the document title includes 'Check for updates', indicating update status — together providing relevant supplementary information about the review type and status."
    }
  ],
  "confidence": 75
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Background: There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The abstract explicitly states the limited existing evidence and frames the uncertainty about how to evaluate sustainability of EBIs."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Through an integrative review, we aimed to identify approaches to evaluate the sustainability of evidence-based interventions (EBIs) and sustainability outcomes.",
      "reason": "The abstract explains the purpose and need for the review — to identify approaches and outcomes given limited existing evidence — demonstrating the importance of conducting the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The discussion explicitly contrasts this review with recent syntheses and explains the distinct need for this review (focus on evaluation), indicating rationale when similar reviews exist."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_20",
      "quote": "As evaluation is necessary to determine effectiveness, this review aimed to improve our understanding of how the sustainability of EBIs in healthcare is evaluated.",
      "reason": "The manuscript is an integrative review focused on evaluation approaches for sustainability rather than a review of intervention effects; thus describing an intervention's mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found in the provided text that a logic model was considered or presented for complex interventions or delivery contexts."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The review objectives are explicitly stated (to identify and synthesize approaches and to enhance understanding of specific aspects), but they are not presented using a formal question-formulation framework (e.g., PICO or similar)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "Integrative reviews can include diverse data sources and do not restrict the type of study design. Furthermore, integrative reviews take a more flexible approach to analysis compared to systematic reviews, combining both quantitative and qualitative data if there are similarities [12-14].",
      "reason": "This is an integrative review of evaluation approaches for sustainability of EBIs, not a review of intervention effects requiring planned comparisons; thus specifying PICO-style comparisons is not applicable."
    }
  ],
  "confidence": "80"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical ­ approach a for sustainability ­ (theory b , ­ model c , ­ framework d , ­ instrument e , method, checklist, process, strategy, conceptual- izations, development, pilot test and/or ­ tool f ) • Were within a healthcare ­ setting g • Evaluated the sustainability of an EBI (Note that inconsistent terminology for EBI is prominent and thus may be referred to as a QI intervention/ initia- tive in the literature).",
      "reason": "Table 1 explicitly lists multiple study-level eligibility characteristics (study type, design/methods, theoretical approach, setting, and evaluation focus)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_21",
      "quote": "We only included published studies in the English language and peer-reviewed primary studies in this review.",
      "reason": "The manuscript specifies language (English) and publication/report status (published, peer-reviewed primary studies) but does not specify any dissemination year range or date-based limits for eligible reports."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit distinction is reported between excluding studies because outcomes were not measured versus excluding because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not specify groups used in each synthesis nor link groups to comparisons defined in the review objectives in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although exclusion criteria are listed, the manuscript does not provide rationales explaining notable restrictions on study eligibility (e.g., why gray literature or non-English studies were excluded)."
    }
  ],
  "confidence": 85
}

