    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No description was found of a process used to select results when not all compatible results were sought."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
