    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No reporting of changes to processes for selecting results within eligible outcome domains with rationales was found in the provided evidence."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "MISSING",
      "chunk_id": "text_19",
      "quote": "Whether or not benefits continued for patients, staff, and stakeholders was the most commonly evaluated outcome of sustainability ( n = 45). The most frequently reported sustained benefits are improved health outcomes and improved quality of care.",
      "reason": "While the manuscript notes which outcomes were most frequently evaluated, it does not state which outcomes were considered most important for interpreting conclusions nor provide a rationale for any prioritisation; therefore the specific reporting required by this item is missing."
    }
  ],
  "confidence": "65"
