      "element_id": "prisma_2020_11_e3",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": \"Each study is assigned an overall quality score, using asterisks representing the quality appraisal of each study. Scores vary from 20% (*) when one criterion is met to 100% (*****) when all criteria are met.\",
      "reason": "An overall risk-of-bias/quality judgement (overall quality score using asterisk/percentage system) and the scoring rules (20% = *, up to 100% = *****) are reported."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided about adaptations made to MMAT or any other risk-of-bias tool."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
